package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;import java.util.*;import org.json.*;
public final class Stage47Instrumentation extends Instrumentation{
 void check(boolean b,String s){if(!b)throw new AssertionError(s);}void note(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 BananaEngine.Result run(Context c,Semilla m,String q)throws Exception{return BananaEngine.run(c,q,new ArrayList<String[]>(),"",true,m);}
 @Override public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();JavaMethodEditor.prefs(c).edit().clear().commit();JavaMethodEditor.loaded=-1;JavaMethodEditor.restore(c);JavaFunction.prefs(c).edit().clear().commit();JavaFunction.loaded=-1;JavaFunction.restore(c);c.getSharedPreferences("shared-scene",0).edit().clear().commit();Semilla model=OwnBrain.load(c);run(c,model,"crea a Fito un zorro");String scene=SceneStore.load(c).json().toString();BananaEngine.Result r=run(c,model,"cambia el metodo del chat: cuando diga \"buenas banana\" responde \"Frutal, vamos a crear\"");check(r.text.contains("Compiló")&&JavaMethodEditor.active==null,"real method source compiled in draft");JSONObject d=new JSONObject(JavaMethodEditor.prefs(c).getString("draft",""));check(d.getInt("pid")!=android.os.Process.myPid()&&d.getInt("tests")>=15,"method tested in separate process");check(d.getString("source").contains("text.equals(\"buenas banana\")")&&!d.has("prior")&&d.has("sourceFile")&&JavaMethodEditor.storedSource(d).equals(d.getString("source")),"real edited source and flat version metadata");check(scene.equals(SceneStore.load(c).json().toString()),"draft does not modify scene");check(run(c,model,"mostrame el cambio de java").text.contains("ANTES:")&&JavaMethodEditor.active==null,"diff does not activate");note("NATIVE_REAL_METHOD_SOURCE_COMPILED_AND_DIFF_OK");
  r=run(c,model,"aplica el cambio del metodo");check(r.text.startsWith("Listo."),"apply passed");r=run(c,model,"buenas banana");check(r.text.equals("Frutal, vamos a crear"),"actual engine conversation uses compiled replacement");check(ChatLanguage.socialReply("gracias").equals(ChatLanguage.socialReplyBase("gracias")),"other original behavior preserved");JavaMethodEditor.loaded=-1;JavaMethodEditor.active=null;JavaMethodEditor.restore(c);check(ChatLanguage.socialReply("buenas banana").equals("Frutal, vamos a crear"),"source and bytecode restore from persistence");note("NATIVE_REAL_CHAT_CHANGED_AND_RELOAD_OK");
  int rev=JavaMethodEditor.prefs(c).getInt("revision",0);r=run(c,model,"cambia el metodo del chat: cuando contenga \"crea\" responde \"No\"");check(r.text.contains("intercepta")&&JavaMethodEditor.prefs(c).getInt("revision",0)==rev,"protected creation control rejects candidate");r=run(c,model,"reescribe el metodo del chat: System.exit(0); return null;");check(r.text.contains("No activé")&&JavaMethodEditor.prefs(c).getInt("revision",0)==rev,"arbitrary APIs rejected before compilation");
  run(c,model,"reescribe el metodo del chat: if (text.startsWith(\"buenas\")) return \"Taller abierto\"; return null;");r=run(c,model,"aplica el cambio del metodo");check(r.text.startsWith("Listo.")&&run(c,model,"buenas noches").text.equals("Taller abierto"),"whole bounded Java method body works");r=run(c,model,"deshace ese ajuste");check(r.text.contains("Recuperé la versión")&&run(c,model,"buenas banana").text.equals("Frutal, vamos a crear"),"generic undo chooses editor");check(scene.equals(SceneStore.load(c).json().toString()),"conversation edits preserve project");note("NATIVE_FULL_METHOD_BODY_CONTROLS_AND_UNDO_OK");
  run(c,model,"cambia el metodo del chat: cuando diga \"modo taller\" responde \"Listos\"");JavaMethodEditor.prefs(c).edit().putInt("revision",JavaMethodEditor.prefs(c).getInt("revision",0)+1).commit();r=run(c,model,"aplica el cambio del metodo");check(r.text.contains("desactualizado")&&ChatLanguage.socialReply("buenas banana").equals("Frutal, vamos a crear"),"stale candidate preserves active");run(c,model,"descarta el cambio del metodo");check(JavaChat.progress.isEmpty()&&JavaChat.owner==null,"progress cleared");
  // Shared trial protocol must still validate the previous release's numeric functions.
  r=run(c,model,"reescribe la funcion del salto: -100*t*(1-t)");check(r.text.contains("Compiló"),"numeric trial protocol preserved");run(c,model,"descarta la funcion del salto");
  result.putString("stream","PASS STAGE47 real Java method source editing, independent process tests, before/after review, activation, actual chat response, persisted restore, bounded full body, protected controls, API rejection, version recovery, stale guard and curve protocol regression.\n");finish(Activity.RESULT_OK,result);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,result);}}
}
